public class TileEntitySteamEngine extends TileEntity implements ITileEntityBase, ITickable, ISoundController, IExtraCapabilityInformation {
    class BurningFuel {
        ItemStack solidFuel = ItemStack.EMPTY;
        FluidStack liquidFuel;
        int timeLeft;

        public BurningFuel() {

        }

        public BurningFuel(ItemStack solidFuel, int timeLeft) {
            this.solidFuel = solidFuel;
            this.timeLeft = timeLeft;
        }

        public BurningFuel(FluidStack liquidFuel, int timeLeft) {
            this.liquidFuel = liquidFuel;
            this.timeLeft = timeLeft;
        }

        public void tick() {
            timeLeft--;
        }

        public void reset() {
            solidFuel = ItemStack.EMPTY;
            liquidFuel = null;
            timeLeft = 0;
        }

        public boolean isSolid() {
            return !solidFuel.isEmpty();
        }

        public boolean isLiquid() {
            return liquidFuel != null;
        }

        public NBTTagCompound writeToNBT(NBTTagCompound tag) {
            if(liquidFuel != null)
                tag.setTag("fluid", liquidFuel.writeToNBT(new NBTTagCompound()));
            if(!solidFuel.isEmpty())
                tag.setTag("item", solidFuel.serializeNBT());
            tag.setInteger("timeLeft",timeLeft);
            return tag;
        }

        public void readFromNBT(NBTTagCompound tag) {
            if(tag.hasKey("fluid"))
                liquidFuel = FluidStack.loadFluidStackFromNBT(tag.getCompoundTag("fluid"));
            if(tag.hasKey("item"))
                solidFuel = new ItemStack(tag.getCompoundTag("item"));
            timeLeft = tag.getInteger("timeLeft");
        }

        public boolean isEmpty() {
            return timeLeft <= 0;
        }

        public Color getColor() {
            if(isSolid())
                return new Color(72,72,72, 128);
            if(isLiquid()) {
                ILiquidFuel fuelHandler = EmbersAPI.getSteamEngineFuel(liquidFuel);
                if(fuelHandler != null)
                    return fuelHandler.getBurnColor(liquidFuel);
            }
            return new Color(0,0,0,0);
        }
    }

    public static int NORMAL_FLUID_THRESHOLD = 10;
    public static int NORMAL_FLUID_CONSUMPTION = 4;
    public static int GAS_CONSUMPTION = 20;
    public static double MAX_POWER = 50;
    public static int CAPACITY = 8000;
    public static double SOLID_POWER = 20;
    public static double FUEL_MULTIPLIER = 2;

    public static final int SOUND_BURN = 1;
    public static final int SOUND_STEAM = 2;
    public static final int[] SOUND_IDS = new int[]{SOUND_BURN, SOUND_STEAM};

    BurningFuel currentFuel = new BurningFuel();

    int ticksExisted = 0;
    //int burnProgress = 0;
    //int steamProgress = 0;
    HashSet<Integer> soundsPlaying = new HashSet<>();
    EnumFacing front = EnumFacing.UP;
    public FluidTank tank = new FluidTank(CAPACITY);
    public DefaultMechCapability capability = new DefaultMechCapability() {
        @Override
        public void setPower(double value, EnumFacing from) {
            if (from == null)
                super.setPower(value, null);
        }
    };
    public ItemStackHandler inventory = new ItemStackHandler(1) {
        @Override
        protected void onContentsChanged(int slot) {
            TileEntitySteamEngine.this.markDirty();
        }

        @Override
        public ItemStack insertItem(int slot, ItemStack stack, boolean simulate) {
            if (TileEntityFurnace.getItemBurnTime(stack) == 0) {
                return stack;
            }
            return super.insertItem(slot, stack, simulate);
        }

        @Override
        public ItemStack extractItem(int slot, int amount, boolean simulate) {
            ItemStack currentFuel = super.extractItem(slot, amount, true);
            int burntime = TileEntityFurnace.getItemBurnTime(currentFuel);
            if (burntime != 0) {
                return ItemStack.EMPTY;
            }
            return super.extractItem(slot, amount, simulate);
        }

    };

    public TileEntitySteamEngine() {
        super();
    }

    @Override
    public NBTTagCompound writeToNBT(NBTTagCompound tag) {
        super.writeToNBT(tag);
        tag.setDouble("mech_power", capability.power);
        tag.setTag("tank", tank.writeToNBT(new NBTTagCompound()));
        tag.setTag("progress", currentFuel.writeToNBT(new NBTTagCompound()));
        tag.setInteger("front", front.getIndex());
        tag.setTag("inventory", inventory.serializeNBT());
        return tag;
    }

    @Override
    public void readFromNBT(NBTTagCompound tag) {
        super.readFromNBT(tag);
        capability.power = tag.getDouble("mech_power");
        tank.readFromNBT(tag.getCompoundTag("tank"));
        currentFuel.readFromNBT(tag.getCompoundTag("progress"));
        inventory.deserializeNBT(tag.getCompoundTag("inventory"));
        front = EnumFacing.getFront(tag.getInteger("front"));
    }

    @Override
    public NBTTagCompound getUpdateTag() {
        return writeToNBT(new NBTTagCompound());
    }

    @Nullable
    @Override
    public SPacketUpdateTileEntity getUpdatePacket() {
        return new SPacketUpdateTileEntity(getPos(), 0, getUpdateTag());
    }

    @Override
    public void onDataPacket(NetworkManager net, SPacketUpdateTileEntity pkt) {
        readFromNBT(pkt.getNbtCompound());
    }

    @Override
    public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
        if (capability == MysticalMechanicsAPI.MECH_CAPABILITY) {
            return facing == front;
        }
        if (capability == CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY) {
            return true;
        }
        if (capability == CapabilityItemHandler.ITEM_HANDLER_CAPABILITY) {
            return true;
        }
        return super.hasCapability(capability, facing);
    }

    @Override
    public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
        if (capability == MysticalMechanicsAPI.MECH_CAPABILITY) {
            return (T) this.capability;
        }
        if (capability == CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY) {
            return (T) tank;
        }
        if (capability == CapabilityItemHandler.ITEM_HANDLER_CAPABILITY) {
            return (T) inventory;
        }
        return super.getCapability(capability, facing);
    }

    @Override
    public void markDirty() {
        super.markDirty();
        Misc.syncTE(this);
    }

    @Override
    public boolean activate(World world, BlockPos pos, IBlockState state, EntityPlayer player, EnumHand hand,
                            EnumFacing side, float hitX, float hitY, float hitZ) {
        ItemStack heldItem = player.getHeldItem(hand);
        //TODO: Any fluid container
        boolean didFill = FluidUtil.interactWithFluidHandler(player, hand, tank);
        if (didFill) {
            this.markDirty();
            return true;
        }
        return false;
    }

    @Override
    public void breakBlock(World world, BlockPos pos, IBlockState state, EntityPlayer player) {
        this.invalidate();
        Misc.spawnInventoryInWorld(world, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, inventory);
        capability.setPower(0f, null);
        updateNearby();
        world.setTileEntity(pos, null);
    }

    public void updateNearby() {
        for (EnumFacing f : EnumFacing.values()) {
            TileEntity t = world.getTileEntity(getPos().offset(f));
            if (t != null && f == front) {
                if (t.hasCapability(MysticalMechanicsAPI.MECH_CAPABILITY, Misc.getOppositeFace(f))) {
                    t.getCapability(MysticalMechanicsAPI.MECH_CAPABILITY, Misc.getOppositeFace(f)).setPower(capability.getPower(Misc.getOppositeFace(f)), Misc.getOppositeFace(f));
                    t.markDirty();
                }
            }
        }
    }

    private ItemStack copyWithSize(ItemStack stack, int size) {
        stack = stack.copy();
        stack.setCount(size);
        return stack;
    }

    @Override
    public void update() {
        IBlockState state = world.getBlockState(getPos());
        if (state.getBlock() instanceof BlockSteamEngine) {
            this.front = state.getValue(BlockSteamEngine.facing);
        }

        boolean dirty = false;
        double powerGenerated = 0;
        if (world.isRemote) {
            spawnParticles();
            handleSound();
        }

        if(!world.isRemote && !currentFuel.isEmpty()) {
            currentFuel.tick();
            if (currentFuel.isEmpty()) {
                currentFuel.reset();
                dirty = true;
            }
        }

        if (currentFuel.isEmpty()) {
            FluidStack fluid = tank.getFluid();
            ILiquidFuel fuelHandler = EmbersAPI.getSteamEngineFuel(fluid);
            if (fluid != null && fuelHandler != null) { //Overclocked steam power
                fluid = tank.drain(Math.min(GAS_CONSUMPTION, Math.max(fluid.amount - 1, 1)), false);
                if (!world.isRemote) {
                    currentFuel = new BurningFuel(fluid, fuelHandler.getTime(fluid));
                    tank.drain(fluid, true);
                    dirty = true;
                }
            } else { //Otherwise try normal power generation from water and coal
                if (!world.isRemote && !inventory.getStackInSlot(0).isEmpty() && fluid != null && fluid.getFluid() == FluidRegistry.WATER && tank.getFluidAmount() >= NORMAL_FLUID_THRESHOLD) {
                    ItemStack fuel = inventory.getStackInSlot(0);
                    if (!fuel.isEmpty()) {
                        ItemStack fuelCopy = fuel.copy();
                        int burnTime = TileEntityFurnace.getItemBurnTime(fuelCopy);
                        if (burnTime > 0) {
                            currentFuel = new BurningFuel(copyWithSize(fuelCopy, 1), (int)(burnTime * FUEL_MULTIPLIER));
                            fuel.shrink(1);
                            if (fuel.isEmpty())
                                inventory.setStackInSlot(0, fuelCopy.getItem().getContainerItem(fuelCopy));
                            dirty = true;
                        }
                    }
                }
            }
        }

        if (currentFuel.isLiquid()) { //Generate liquid power
            FluidStack fluid = currentFuel.liquidFuel;
            ILiquidFuel fuelHandler = EmbersAPI.getSteamEngineFuel(fluid);
            powerGenerated = Misc.getDiminishedPower(fuelHandler.getPower(fluid), MAX_POWER, 1);
        }

        if (currentFuel.isSolid()) { //Generate solid power
            FluidStack fluid = tank.getFluid();
            if (tank.getFluidAmount() >= NORMAL_FLUID_CONSUMPTION && fluid != null && fluid.getFluid() == FluidRegistry.WATER) {
                if (!world.isRemote) {
                    tank.drain(NORMAL_FLUID_CONSUMPTION, true);
                    powerGenerated = SOLID_POWER;
                    dirty = true;
                }
            } else {
                currentFuel.reset(); //Waste the rest of the fuel
            }
        }

        if(dirty)
            markDirty();

        if (!world.isRemote && capability.getPower(null) != powerGenerated) {
            capability.setPower(powerGenerated, null);
            updateNearby();
        }
    }

    private void spawnParticles() {
        if (currentFuel.isEmpty())
            return;
        boolean vapor = currentFuel.isLiquid();
        for (int i = 0; i < 4; i++) {
            float offX = 0.09375f + 0.8125f * (float) Misc.random.nextInt(2);
            float offZ = 0.28125f + 0.4375f * (float) Misc.random.nextInt(2);
            if (front.getAxis() == EnumFacing.Axis.X) {
                float h = offX;
                offX = offZ;
                offZ = h;
            }

            Color color = currentFuel.getColor();

            if (vapor)
                ParticleUtil.spawnParticleVapor(world,
                        getPos().getX() + offX, getPos().getY() + 1.0f, getPos().getZ() + offZ,
                        0.025f * (Misc.random.nextFloat() - 0.5f), 0.125f * (Misc.random.nextFloat()), 0.025f * (Misc.random.nextFloat() - 0.5f),
                        color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() / 255f, 0.5f, 2.0f + Misc.random.nextFloat(), 24);
            else
                ParticleUtil.spawnParticleSmoke(world,
                        getPos().getX() + offX, getPos().getY() + 1.0f, getPos().getZ() + offZ,
                        0.025f * (Misc.random.nextFloat() - 0.5f), 0.125f * (Misc.random.nextFloat()), 0.025f * (Misc.random.nextFloat() - 0.5f),
                        color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() / 255f, 2.0f + Misc.random.nextFloat(), 24);
        }
    }

    @Override
    public void playSound(int id) {
        float soundX = (float) pos.getX() + 0.5f;
        float soundY = (float) pos.getY() + 0.5f;
        float soundZ = (float) pos.getZ() + 0.5f;
        switch (id) {
            case SOUND_BURN:
                Embers.proxy.playMachineSound(this, SOUND_BURN, SoundManager.STEAM_ENGINE_LOOP_BURN, SoundCategory.BLOCKS, true, 1.0f, 1.0f, soundX, soundY, soundZ);
                world.playSound(soundX, soundY, soundZ, SoundManager.STEAM_ENGINE_START_BURN, SoundCategory.BLOCKS, 1.0f, 1.0f, false);
                break;
            case SOUND_STEAM:
                Embers.proxy.playMachineSound(this, SOUND_STEAM, SoundManager.STEAM_ENGINE_LOOP_STEAM, SoundCategory.BLOCKS, true, 1.0f, 1.0f, soundX, soundY, soundZ);
                world.playSound(soundX, soundY, soundZ, SoundManager.STEAM_ENGINE_START_STEAM, SoundCategory.BLOCKS, 1.0f, 1.0f, false);
                break;
        }
        soundsPlaying.add(id);
    }

    @Override
    public void stopSound(int id) {
        world.playSound((float) pos.getX() + 0.5f, (float) pos.getY() + 0.5f, (float) pos.getZ() + 0.5f, SoundManager.STEAM_ENGINE_STOP, SoundCategory.BLOCKS, 1.0f, 1.0f, false);
        soundsPlaying.remove(id);
    }

    @Override
    public boolean isSoundPlaying(int id) {
        return soundsPlaying.contains(id);
    }

    @Override
    public int[] getSoundIDs() {
        return SOUND_IDS;
    }

    @Override
    public boolean shouldPlaySound(int id) {
        switch (id) {
            case SOUND_BURN:
                return currentFuel.isSolid();
            case SOUND_STEAM:
                return currentFuel.isLiquid();
        }
        return false;
    }

    @Override
    public boolean hasCapabilityDescription(Capability<?> capability) {
        return capability == CapabilityItemHandler.ITEM_HANDLER_CAPABILITY || capability == CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY;
    }

    @Override
    public void addCapabilityDescription(List<String> strings, Capability<?> capability, EnumFacing facing) {
        if (capability == CapabilityItemHandler.ITEM_HANDLER_CAPABILITY)
            strings.add(IExtraCapabilityInformation.formatCapability(EnumIOType.INPUT, "embers.tooltip.goggles.item", I18n.format("embers.tooltip.goggles.item.fuel")));
        if (capability == CapabilityFluidHandler.FLUID_HANDLER_CAPABILITY)
            strings.add(IExtraCapabilityInformation.formatCapability(EnumIOType.INPUT, "embers.tooltip.goggles.fluid", I18n.format("embers.tooltip.goggles.fluid.water_or_steam")));
    }
}

package com.lothrazar.cyclic.block.cable;

import com.google.common.collect.Maps;
import com.lothrazar.cyclic.ModCyclic;
import com.lothrazar.cyclic.block.TileBlockEntityCyclic;
import com.lothrazar.cyclic.block.cable.energy.TileCableEnergy;
import com.lothrazar.cyclic.block.cable.fluid.TileCableFluid;
import com.lothrazar.cyclic.capabilities.block.FluidTankBase;
import com.lothrazar.cyclic.item.datacard.fluid.FluidFilterCardItem;
import com.lothrazar.cyclic.registry.ItemRegistry;
import com.lothrazar.cyclic.util.CapabilityUtil;
import com.lothrazar.cyclic.util.FluidHelpers;
import com.lothrazar.library.cap.EnergyStorageWrapper;
import com.lothrazar.library.core.ITileFacade;
import com.lothrazar.library.util.DirectionUtil;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.core.HolderLookup;
import net.neoforged.neoforge.energy.IEnergyStorage;
import net.neoforged.neoforge.fluids.FluidType;
import net.neoforged.neoforge.fluids.capability.IFluidHandler;
import net.neoforged.neoforge.items.IItemHandler;
import net.neoforged.neoforge.items.ItemStackHandler;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public abstract class TileCableBase extends TileBlockEntityCyclic implements ITileFacade {

  protected final Map<Direction, Integer> mapIncomingEnergy = Maps.newHashMap();
  protected final Map<Direction, FluidTankBase> mapFluidFlow = new ConcurrentHashMap<>();
  protected final Map<Direction, IItemHandler> mapItemFlow = new ConcurrentHashMap<>();

  private boolean isEnergyCable = false;
  private boolean isItemCable = false;
  private boolean isFluidCable = false;

  public boolean isEnergyCable() { return isEnergyCable; }
  public boolean isItemCable() { return isItemCable; }
  public boolean isFluidCable() { return isFluidCable; }
  // energy has no filter
  // item has no flow configs
  protected static final int FLOW_QTY = 64; // fixed, for non-extract motion
  protected EnergyStorageWrapper energy;

  public ItemStackHandler itemFilter = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      return stack.getItem() == ItemRegistry.FILTER_DATA.get();
    }
  };
  public final ItemStackHandler fluidFilter = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      return stack.getItem() == ItemRegistry.FILTER_FLUID.get();
    }
  };

  public TileCableBase(BlockEntityType<?> tileEntityTypeIn, BlockPos pos, BlockState state) {
    super(tileEntityTypeIn, pos, state);
  }

  @Override
  public void setField(int field, int value) {}

  @Override
  public int getField(int field) {
    return 0;
  }

  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    this.loadFacade(tag);
    if (this.isEnergyCable) {
      for (Direction f : Direction.values()) {
        mapIncomingEnergy.put(f, tag.getInt(f.getSerializedName() + "_incenergy"));
      }
      if (tag.contains(NBTENERGY)) {
        energy.deserializeNBT(registries, tag.get(NBTENERGY));
      }
    }
    if(this.isItemCable()) {
      IItemHandler item;
      for (Direction f : Direction.values()) {
        item = mapItemFlow.get(f);
        if(item !=null){ //item.ifPresent(h -> {
          CompoundTag itemTag = tag.getCompound("item" + f.toString());
          ((ItemStackHandler)item).deserializeNBT(registries, itemTag);
        }
      }
      itemFilter.deserializeNBT(registries,tag.getCompound("itemFilter"));
    }
    if(this.isFluidCable()) {

      fluidFilter.deserializeNBT(registries,tag.getCompound("filter"));
      FluidTankBase fluidh;
      for (Direction dir : Direction.values()) {
        fluidh = mapFluidFlow.get(dir);
        if (tag.contains("fluid" + dir.toString())) {
          fluidh.readFromNBT(registries,tag.getCompound("fluid" + dir.toString()));
        }
      }
    }
    super.loadAdditional(tag, registries);
  }
  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    this.saveFacade(tag);
    if (this.isEnergyCable) {
      for (Direction f : Direction.values()) {
        tag.putInt(f.getSerializedName() + "_incenergy", mapIncomingEnergy.get(f));
      }
      tag.put(NBTENERGY, energy.serializeNBT(registries));
    }
    if(this.isItemCable()) {

      tag.put("itemFilter", itemFilter.serializeNBT(registries));
      IItemHandler item;
      for (Direction f : Direction.values()) {
        item = mapItemFlow.get(f);
        if (item != null) {
          CompoundTag compound = ((ItemStackHandler) item).serializeNBT(registries);
          tag.put("item" + f.toString(), compound);
        }
      }
    }
    if(this.isFluidCable()) {

      tag.put("filter", fluidFilter.serializeNBT(registries));
      FluidTankBase fluidh;
      for (Direction dir : Direction.values()) {
        fluidh = mapFluidFlow.get(dir);
        CompoundTag fluidtag = new CompoundTag();
        if (fluidh != null) {
          fluidh.writeToNBT(registries, fluidtag);
        }
        tag.put("fluid" + dir.toString(), fluidtag);
      }
    }
    super.saveAdditional(tag, registries);
  }

  protected void setIsEnergy() {
    for (Direction f : Direction.values()) {
      mapIncomingEnergy.put(f, 0);
    }
    energy = new EnergyStorageWrapper(TileCableEnergy.BUFFERSIZE.get(),
        TileCableEnergy.TRANSFER_RATE.get());
    isEnergyCable = true;
  }

  protected void setIsItem() {
    for (Direction f : Direction.values()) {
      mapItemFlow.put(f, new ItemStackHandler(1));
    }
    this.isItemCable = true;
  }
  protected void setIsFluid() {
    for (Direction f : Direction.values()) {
      mapFluidFlow.put(f, new FluidTankBase(this, TileCableFluid.BUFFERSIZE.get() * FluidHelpers.FluidAttributes.BUCKET_VOLUME, p -> true));
    }
    this.isFluidCable = true;
  }
  private CompoundTag facadeState = null;

  @Override
  public CompoundTag getFacade() {
    return facadeState;
  }

  @Override
  public void setFacade(CompoundTag facadeState) {
    this.facadeState = facadeState;
  }

  protected static final int TIMER_SIDE_INPUT = 15;

  protected boolean isEnergyIncomingFromFace(Direction face) {
    return mapIncomingEnergy.get(face) > 0;
  }

  public void updateIncomingEnergyFace(Direction inputFrom) {
    mapIncomingEnergy.put(inputFrom, TIMER_SIDE_INPUT);
  }

  // --- shared tick methods called by subclasses and TileCableBundled ---

  protected void tickEnergy() {
    this.syncEnergy();
    this.tickDownIncomingPowerFaces();
    this.tickEnergyCableFlow();
    for (final Direction extractSide : Direction.values()) {
      final EnumConnectType connection = getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(extractSide));
      if (connection.isExtraction()) {
        tryExtractEnergyFrom(extractSide);
      }
    }
  }

  protected void tickDownIncomingPowerFaces() {
    for (final Direction incomingDirection : Direction.values()) {
      mapIncomingEnergy.computeIfPresent(incomingDirection, (direction, amount) -> {
        if (amount > 0) {
          amount -= 1;
        }
        return amount;
      });
    }
  }

  private void tickEnergyCableFlow() {
    for (final Direction outgoingSide : DirectionUtil.getAllInDifferentOrder()) {
      EnumConnectType connection = this.getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(outgoingSide));
      if (connection.isExtraction() || connection.isBlocked()) {
        continue;
      }
      if (!this.isEnergyIncomingFromFace(outgoingSide)) {
        moveEnergy(outgoingSide, TileCableEnergy.TRANSFER_RATE.get());
      }
    }
  }

  protected void tickItem() {
    for (Direction extractSide : Direction.values()) {
      EnumConnectType connection = this.getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(extractSide));
      if (connection.isExtraction()) {
        final IItemHandler sideHandler = mapItemFlow.get(extractSide);
        tryExtract(sideHandler, extractSide, FLOW_QTY, itemFilter);
      }
    }
    tickItemNormalFlow();
  }

  private void tickItemNormalFlow() {
    incomingSideLoop: for (final Direction incomingSide : Direction.values()) {
      final IItemHandler sideHandler = mapItemFlow.get(incomingSide);
      for (final Direction outgoingSide : DirectionUtil.getAllInDifferentOrder()) {
        if (outgoingSide == incomingSide) {
          continue;
        }
        if (!itemCanPushToSide(outgoingSide)) {
          continue;
        }
        if (this.moveItems(outgoingSide, FLOW_QTY, sideHandler)) {
          continue incomingSideLoop;
        }
      }
      if (itemCanPushToSide(incomingSide)) {
        this.moveItems(incomingSide, FLOW_QTY, sideHandler);
      }
    }
  }

  private boolean itemCanPushToSide(Direction outgoingSide) {
    EnumConnectType outgoingConnection = getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(outgoingSide));
    return !outgoingConnection.isExtraction() && !outgoingConnection.isBlocked();
  }

  protected void tickFluid() {
    for (Direction extractSide : Direction.values()) {
      EnumConnectType connection = this.getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(extractSide));
      if (connection.isExtraction()) {
        tryExtractFluidFrom(extractSide, fluidFilter);
      }
    }
    tickFluidNormalFlow();
  }

  private void tryExtractFluidFrom(Direction extractSide, ItemStackHandler filterIn) {
    if (extractSide == null) {
      return;
    }
    ItemStack filterSta = filterIn == null ? ItemStack.EMPTY : filterIn.getStackInSlot(0);
    final BlockPos target = this.worldPosition.relative(extractSide);
    final Direction incomingSide = extractSide.getOpposite();
    final IFluidHandler tankTarget = CapabilityUtil.fluid(level, target, incomingSide);
    if (tankTarget != null
        && tankTarget.getTanks() > 0
        && !FluidFilterCardItem.filterAllowsExtract(filterSta, tankTarget.getFluidInTank(0))) {
      return;
    }
    if (FluidHelpers.tryFillPositionFromTank(level, worldPosition, extractSide, tankTarget, TileCableFluid.TRANSFER_RATE.get())) {
      return;
    }
    FluidTankBase sideHandler = mapFluidFlow.get(extractSide);
    if (sideHandler != null && sideHandler.getSpace() >= FluidType.BUCKET_VOLUME) {
      FluidHelpers.extractSourceWaterloggedCauldron(level, target, sideHandler, filterSta);
    }
  }

  private void tickFluidNormalFlow() {
    for (Direction incomingSide : Direction.values()) {
      final FluidTankBase sideHandler = mapFluidFlow.get(incomingSide);
      if (sideHandler.getFluidAmount() <= 0) {
        continue;
      }
      int amountBefore = sideHandler.getFluidAmount();
      for (final Direction outgoingSide : DirectionUtil.getAllInDifferentOrder()) {
        if (outgoingSide == incomingSide) {
          continue;
        }
        EnumConnectType connection = this.getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(outgoingSide));
        if (connection.isExtraction() || connection.isBlocked()) {
          continue;
        }
        this.moveFluids(outgoingSide, worldPosition.relative(outgoingSide), TileCableFluid.TRANSFER_RATE.get(), sideHandler);
      }
      // dead-end fallback: if nothing drained forward, allow flowing back
      if (sideHandler.getFluidAmount() == amountBefore) {
        EnumConnectType incomingConn = getBlockState().getValue(CableBase.FACING_TO_PROPERTY_MAP.get(incomingSide));
        if (!incomingConn.isExtraction() && !incomingConn.isBlocked()) {
          this.moveFluids(incomingSide, worldPosition.relative(incomingSide), TileCableFluid.TRANSFER_RATE.get(), sideHandler);
        }
      }
    }
  }

  protected void tryExtractEnergyFrom(Direction extractSide) {
    if (extractSide == null) {
      return;
    }
    final BlockPos posTarget = this.worldPosition.relative(extractSide);

    final IEnergyStorage itemHandlerFrom = CapabilityUtil.energy(level, posTarget, extractSide.getOpposite());

    if (itemHandlerFrom == null) {
      return;
    }
    final int capacity = energy.getMaxEnergyStored() - energy.getEnergyStored();
    if (capacity <= 0) {
      return;
    }
    //first we simulate
    final int energyToExtract = itemHandlerFrom.extractEnergy(TileCableEnergy.TRANSFER_RATE.get(), true);
    if (energyToExtract <= 0) {
      return;
    }
    final int energyReceived = energy.receiveEnergy(energyToExtract, false);
    if (energyReceived <= 0) {
      return;
    }
    final int energyExtracted = itemHandlerFrom.extractEnergy(energyReceived, false);
    //sanity check
    if (energyExtracted != energyReceived) {
      ModCyclic.LOGGER.error("Imbalance extracting energy, extracted " + energyExtracted + " received " + energyReceived);
    }
  }


  @Override
  public IItemHandler getItemHandler(Direction side) {
    if (this.isItemCable() &&
        side != null &&
        !CableBase.isCableBlocked(this.getBlockState(), side)) {
      return mapItemFlow.get(side);
    }
    return null;
  }

  @Override
  public IFluidHandler getFluidHandler(Direction side) {
    if (this.isFluidCable() &&
        side != null &&
        !CableBase.isCableBlocked(this.getBlockState(), side)) {
      return mapFluidFlow.get(side);
    }
    return null;
  }

  @Override
  public IEnergyStorage getEnergyHandler(Direction side) {
    if (this.isEnergyCable() &&
        side != null &&
        !CableBase.isCableBlocked(this.getBlockState(), side)) {
      return energy;
    }
    return null;
  }

}

package com.lothrazar.cyclic.block.collectfluid;

